// TEST-ONLY stand-in for vite-plugin-pwa's virtual:pwa-register. Registers a small
// precaching service worker generated by test/build.mjs (the real build uses Workbox).
export function registerSW(_o?: unknown) {
  if ('serviceWorker' in navigator) navigator.serviceWorker.register('./sw.js').catch((e) => console.warn('sw', e));
  return () => Promise.resolve();
}
